CollectionUtil = {}

---@param area IArea
---@param ray Vector3[]
function CollectionUtil.intersectWithAABB(area, ray)
    if #ray < 2 then
        return
    end
    local tempMin = 0
    local tempMax = 10000
    local dir = VectorUtil.newVector3(ray[2].x - ray[1].x, ray[2].y - ray[1].y, ray[2].z - ray[1].z)
    if math.abs(dir.x) < 0.000001 then
        if ray[1].x < area.minX or ray[1].x > area.maxX then
            return false
        end
    else
        local ood = 1.0 / dir.x
        local t1 = (area.minX - ray[1].x) * ood
        local t2 = (area.maxX - ray[1].x) * ood
        if t1 > t2 then
            local temp = t1
            t1 = t2
            t2 = temp
        end
        if t1 > tempMin then
            tempMin = t1
        end
        if t2 < tempMax then
            tempMax = t2
        end
        if tempMin > tempMax then
            return false
        end
    end
    if math.abs(dir.y) < 0.000001 then
        if ray[1].y < area.minY or ray[1].y > area.maxY then
            return false
        end
    else
        local ood = 1.0 / dir.y
        local t1 = (area.minY - ray[1].y) * ood
        local t2 = (area.maxY - ray[1].y) * ood
        if t1 > t2 then
            local temp = t1
            t1 = t2
            t2 = temp
        end
        if t1 > tempMin then
            tempMin = t1
        end
        if t2 < tempMax then
            tempMax = t2
        end
        if tempMin > tempMax then
            return false
        end
    end
    if math.abs(dir.z) < 0.000001 then
        if ray[1].z < area.minZ or ray[1].z > area.maxZ then
            return false
        end
    else
        local ood = 1.0 / dir.z
        local t1 = (area.minZ - ray[1].z) * ood
        local t2 = (area.maxZ - ray[1].z) * ood
        if t1 > t2 then
            local temp = t1
            t1 = t2
            t2 = temp
        end
        if t1 > tempMin then
            tempMin = t1
        end
        if t2 < tempMax then
            tempMax = t2
        end
        if tempMin > tempMax then
            return false
        end
    end
    return true
end